26: func RankEntries(entries []dossiers.Entry, targetAnchors []string) []RankedEntry {
27: 	var ranked []RankedEntry
28: 	
29: 	targetSet := make(map[string]bool)
30: 	for _, a := range targetAnchors {
31: 		targetSet[a] = true
32: 	}
33: 
34: 	for _, e := range entries {
35: 		score := 0
36: 		anchorMatch := ""
37: 		
38: 		// 1. Anchor match
39: 		if len(e.Anchors) == 0 {
40: 			score += 100
41: 			anchorMatch = "scope"
42: 		} else {
43: 			matchedExact := false
44: 			for _, a := range e.Anchors {
45: 				if targetSet[a] {
46: 					matchedExact = true
47: 					break
48: 				}
49: 			}
50: 			if matchedExact {
51: 				score += 1000
52: 				anchorMatch = "exact"
53: 			} else {
54: 				matchedDir := false
55: 				for _, ta := range targetAnchors {
56: 					for _, a := range e.Anchors {
57: 						if len(ta) > len(a) && ta[:len(a)] == a && (ta[len(a)] == '/' || a[len(a)-1] == '/') {
58: 							matchedDir = true
59: 							break
60: 						}
61: 					}
62: 					if matchedDir {
63: 						break
64: 					}
65: 				}
66: 				if matchedDir {
67: 					score += 500
68: 					anchorMatch = "directory"
69: 				}
70: 			}
71: 		}
72: 
73: 		// 2. Entry type
74: 		score += typeOrderRanking[e.Type]
75: 
76: 		// 3. Verification status
77: 		if e.Verified != "" {
78: 			score += 200
79: 		}
80: 
81: 		// 4. Evidence count
82: 		evScore := len(e.Evidence) * 10
83: 		if evScore > 50 {
84: 			evScore = 50
85: 		}
86: 		score += evScore
87: 
88: 		ranked = append(ranked, RankedEntry{
89: 			Entry:       e,
90: 			Score:       score,
91: 			AnchorMatch: anchorMatch,
92: 		})
93: 	}
94: 
95: 	sort.Slice(ranked, func(i, j int) bool {
96: 		return ranked[i].Score > ranked[j].Score
97: 	})
98: 
99: 	return ranked
100: }
101: 
102: func SelectWithinBudget(ranked []RankedEntry, tokenBudget int) []RankedEntry {
103: 	var selected []RankedEntry
104: 	usedTokens := 0
105: 	
106: 	for _, r := range ranked {
107: 		tokens := len(r.Entry.Text) / 4
108: 		if tokens == 0 {
109: 			tokens = 1
110: 		}
111: 		if usedTokens+tokens <= tokenBudget {
112: 			selected = append(selected, r)
113: 			usedTokens += tokens
114: 		}
115: 	}
116: 	
117: 	return selected
118: }
